'use strict';
(() => {
  const data=window.GameData,{types,byId,initial,calculate,buildPlan,version}=data;
  const $=s=>document.querySelector(s),own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
  const totalTypes=Object.keys(types).length,saveKey='gamebti-rounds-save-v3';
  let book=window.GameCollection.create(types,()=>localStorage);
  let roundIndex=0;
  let answers={},plan=[...data.rounds[0]],current=0,result=null,screen='home',filter='unlocked',pendingGift=null,toastTimer;
  const mobile=matchMedia('(max-width:640px)');
  const whaleMark='<img class="whale-mark" src="assets/whale-mark.svg" width="24" height="18" alt="">';
  const lockIcon='<svg viewBox="0 0 40 48" fill="none" aria-hidden="true"><path d="M10 20v-8a10 10 0 0 1 20 0v8" stroke="currentColor" stroke-width="3"/><rect x="3" y="20" width="34" height="25" rx="5" stroke="currentColor" stroke-width="3"/><path d="M20 29v7" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>';
  function character(code,className='card-icon'){const t=types[code],i=t.spriteIndex;return `<svg class="whale-sprite ${className}" viewBox="${i%4} ${Math.floor(i/4)} 1 1" aria-hidden="true"><image href="${t.sheet}" width="4" height="4" preserveAspectRatio="none"/></svg>`;}
  $('#whale-cast').innerHTML=character('G039','whale-companion whale-left')+character('G031','whale-main')+character('G042','whale-companion whale-right');
  function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
  function closeDialogs(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
  function openDialog(d){d.showModal();document.body.classList.add('dialog-open');d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');},{once:true});}
  function showScreen(next){screen=next;document.body.dataset.screen=next;['home','quiz','result'].forEach(id=>$('#'+id).hidden=id!==next);scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});if(next==='home')updateResume();}
  function save(){try{localStorage.setItem(saveKey,JSON.stringify({version,answers,current,roundIndex,complete:!!result}));}catch{notify('这次仍可继续作答，但浏览器没能保存进度。');}}
  function readSave(){try{const s=JSON.parse(localStorage.getItem(saveKey));if(s?.version!==version||!s.answers||typeof s.answers!=='object'||Array.isArray(s.answers))return null;if(Object.keys(s.answers).some(id=>!byId[id]||!data.has(s.answers,id)))return null;if(!Number.isInteger(s.roundIndex)||s.roundIndex<0||s.roundIndex>2)return null;const ids=buildPlan(s.answers,s.roundIndex);if(!Number.isInteger(s.current)||s.current<0||s.current>=ids.length)return null;if(s.complete)calculate(s.answers,s.roundIndex);return {...s,plan:ids};}catch{return null;}}
  function updateResume(){const s=readSave();$('#resume-button').hidden=!s;$('#resume-button').textContent=s?.complete?`查看第 ${s.roundIndex+1} 小轮结果${s.roundIndex<2?'，或继续下一轮':''} →`:`第 ${s?s.roundIndex+1:1} 小轮进度已保存，接着第 ${s?s.current+1:1} 题 →`;}
  function start(){closeDialogs();answers={};roundIndex=0;plan=[...data.rounds[0]];current=0;result=null;save();renderQuiz();showScreen('quiz');}
  function phaseInfo(){const phase=byId[plan[current]].phase,ids=plan.filter(id=>byId[id].phase===phase);return {phase,index:ids.indexOf(plan[current])+1,total:ids.length,label:phase==='initial'?'发现你的玩法':'确认一下'};}
  function renderQuiz(){
    const id=plan[current],q=byId[id],phase=phaseInfo(),selected=own(answers,id)?answers[id]:null,finish=current===plan.length-1&&(q.phase==='confirm'||data.buildPlan(answers,roundIndex).length===plan.length&&phase.index===14);
    $('#quiz').innerHTML=`${roundStrip()}<div class="quiz-toolbar"><button class="back-link" data-action="home">← 先回大厅</button><span class="quiz-phase">${phase.label} <b class="mono">${String(phase.index).padStart(2,'0')} / ${phase.total}</b></span></div><div class="progress-track" role="progressbar" aria-label="${phase.label}进度" aria-valuemin="0" aria-valuemax="${phase.total}" aria-valuenow="${phase.index}"><div class="progress-fill" style="width:${phase.index/phase.total*100}%"></div></div><h2 class="question-title" id="question-title">${q.title}</h2><div class="answers frequency-answers" role="group" aria-labelledby="question-title">${q.options.map((option,index)=>`<button class="answer ${selected===index?'selected':''} ${option.value===null?'answer-na':''}" data-answer="${index}" aria-pressed="${selected===index}"><span class="answer-key">${option.value===null?'—':index+1}</span><span>${option.label}</span></button>`).join('')}</div><div class="quiz-bottom"><button class="quiz-prev" data-action="previous" ${current===0?'disabled':''}>← 上一题</button><button class="button button-dark quiz-next" data-action="next" ${selected===null?'disabled':''}>${finish?'领取本轮人格':'下一题'} <span>→</span></button></div>`;
  }
  function next(){
    if(!data.has(answers,plan[current]))return;
    if(byId[plan[current]].phase==='initial'&&data.rounds[roundIndex].every(id=>data.has(answers,id)))plan=buildPlan(answers,roundIndex);
    if(current===plan.length-1){const missing=plan.findIndex(id=>!data.has(answers,id));if(missing!==-1){current=missing;save();renderQuiz();scrollTo(0,0);return;}result=calculate(answers,roundIndex);for(const code of result.primaryIds)unlock(code,'self');save();renderResult();showScreen('result');return;}
    current++;save();renderQuiz();scrollTo(0,0);$('#question-title').setAttribute('tabindex','-1');$('#question-title').focus({preventScroll:true});
  }
  function labelSection(){return '';}
  function roundStrip(){return `<div class="round-strip" aria-label="一大轮，三个小轮">${[0,1,2].map(n=>`<span class="${n===roundIndex?'active':n<roundIndex?'done':''}">${n<roundIndex?'✓':n+1} 第${n+1}小轮</span>`).join('')}</div>`;}
  function roundHeader(){const final=roundIndex===2;return `${roundStrip()}<div class="round-summary"><span class="section-kicker mono">${final?'YOUR PLAYER COMBO':'PLAYER UNLOCKED'}</span><h2>${final?'你的玩家人格是……':'发现了，你的另一面。'}</h2><p class="combo-names">${result.primaryIds.length?result.primaryIds.map(c=>types[c].name).join(' + '):'还没找到最像你的那一面'}</p>${result.roundResults.some(r=>r.tied.length>1)?`<p>也有点像：${[...new Set(result.roundResults.flatMap(r=>r.tied.filter(c=>c!==r.code)))].map(c=>types[c].name).join('、')}。</p>`:''}${final?'':`<button class="button button-dark round-continue" data-action="continue-round">继续探索 →</button>`}</div>`;}
  function continueRound(){if(!result||roundIndex>=2)return;closeDialogs();roundIndex++;current=0;plan=buildPlan(answers,roundIndex);result=null;save();renderQuiz();showScreen('quiz');}
  function renderResult(){
    if(!result.code){$('#result').innerHTML=`${roundHeader()}<div class="insufficient-result"><p>这次遇到的情境，可能还不够像你。</p><button class="button button-outline" data-action="start">重新测测 ↻</button><button class="text-link" data-action="collection">我的图鉴 →</button></div>`;return;}
    const t=types[result.code];
    $('#result').innerHTML=`${roundHeader()}<div class="result-heading"><span class="section-kicker mono">YOUR PLAY STYLE, THIS TIME</span><h2>收下你的玩家人格</h2></div><div class="result-type-picker" aria-label="选择要查看和分享的倾向">${result.primaryIds.map(code=>`<button class="${code===result.code?'active':''}" data-result-type="${code}" aria-pressed="${code===result.code}">${types[code].name}</button>`).join('')}</div><div class="result-layout"><div class="identity-card card-${t.group}" id="identity-card"><div class="identity-top"><b class="identity-brand">gamebti ${whaleMark}</b><span class="mono">PLAYER ID CARD</span></div><div class="identity-code">${result.code}</div><h3>${t.name}</h3><span class="identity-en">${t.category}</span>${character(result.code,'identity-character')}<p class="identity-quote">“${t.quote}”</p><div class="identity-tags"><span>${t.trait}</span></div><div class="identity-foot"><span>你的玩法，不只一种。</span><span class="mono">VOL. 002</span></div></div><div class="result-detail"><h3>${t.trait}</h3><p class="result-intro">${t.intro}</p><div class="result-habits"><h3>放进游戏里，大概是这样</h3><p>${t.example}</p><h3>和相近类型，差在哪？</h3><p>${t.distinction}</p></div><div class="result-mate"><b>下次联机，可以先说清这件事</b><br>${t.tip}</div>${labelSection()}</div></div><div class="result-actions"><button class="button button-dark" data-action="download">保存这张人格卡 <span>↓</span></button><button class="button button-outline" data-action="share">送朋友这张人格 ↗</button><button class="button button-outline" data-action="start">再测一次 ↻</button><button class="text-link" data-action="collection">我的图鉴 →</button></div>`;
    placeResultActions();
  }
  function placeResultActions(){const actions=$('#result .result-actions'),layout=$('#result .result-layout');if(!actions||!layout)return;if(mobile.matches)layout.insertBefore(actions,$('#result .result-detail'));else layout.after(actions);}
  mobile.addEventListener('change',placeResultActions);
  function lockedCard(n){return `<div class="player-card card-locked" aria-label="第 ${n} 格，未解锁"><div class="card-top"><span class="card-code">???</span><span class="card-number">NO.${String(n).padStart(2,'0')}</span></div><div class="locked-glyph">${lockIcon}</div><h3>尚未遇见</h3><p class="card-quote">做次测试，或收下朋友的人格卡。</p></div>`;}
  function card(code){const index=Object.keys(types).indexOf(code),t=types[code],source=book.source(code);if(!book.has(code))return lockedCard(index+1);return `<button class="player-card card-${t.group}" data-type="${code}" aria-label="了解 ${code} ${t.name}"><div class="card-top"><span class="card-code">${code}</span><span class="card-number">NO.${String(index+1).padStart(2,'0')}</span></div><div class="card-body"><div><h3>${t.name}</h3><span class="card-sub">${t.category}</span></div>${character(code)}</div><p class="card-quote">“${t.quote}”</p><span class="card-source">${source.self?(source.friend?'自己测出 · 也收到过':'自己测出的'):'朋友送来的'}</span><span class="card-arrow">↗</span></button>`;}
  function emptyCollection(){return `<div class="collection-empty"><div class="empty-lock">${lockIcon}</div><h3>${filter==='friend'?'还没收到搭子的人格卡':'新的一页，等你来开。'}</h3><p>${filter==='friend'?'让朋友把新版结果链接发给你，点开就能收进图鉴。':'测测自己的玩法，收下第一张人格卡。'}</p>${filter==='friend'?'':'<button class="button button-dark" data-action="start">解锁我的玩家倾向 <span>↗</span></button>'}</div>`;}
  function renderCollection(){const codes=Object.keys(types).filter(code=>filter==='all'||(filter==='unlocked'?book.has(code):book.source(code)[filter]));$('#collection-grid').innerHTML=codes.length?codes.map(card).join(''):emptyCollection();const unlocked=book.codes();$('#collection-count').textContent=unlocked.length+'/'+totalTypes;$('#collection-progress-fill').style.width=unlocked.length/totalTypes*100+'%';$('#collection-filters').querySelectorAll('button').forEach(button=>{const kind=button.dataset.filter;button.classList.toggle('active',kind===filter);button.querySelector('span').textContent=kind==='all'?totalTypes:kind==='unlocked'?unlocked.length:unlocked.filter(code=>book.source(code)[kind]).length;});}
  function refreshCollection(){const codes=book.codes();$('#nav-unlocked').textContent=codes.length+'/'+totalTypes;$('#featured-players').innerHTML=codes.length?codes.slice(-4).map(card).join(''):emptyCollection();if($('#collection-dialog').open)renderCollection();}
  function unlock(code,source){const state=book.unlock(code,source);refreshCollection();if(!state.persisted)notify('这次已解锁，但浏览器没能保存图鉴。');return state;}
  function openCollection(code){closeDialogs();filter='unlocked';renderCollection();openDialog($('#collection-dialog'));if(code)previewType(code);}
  function previewType(code){if(!book.has(code))return;const t=types[code];$('#collection-grid .type-preview-detail')?.remove();$('#collection-grid').querySelectorAll('.player-card').forEach(card=>card.classList.toggle('selected',card.dataset.type===code));const detail=document.createElement('div');detail.className='type-preview-detail';detail.innerHTML=`<h3>${code} · ${t.name}</h3><p>${t.intro}</p><h4>典型表现</h4><p>${t.example}</p><h4>容易混淆的区别</h4><p>${t.distinction}</p><button class="text-link" data-action="start">再测测这次的玩法 →</button>`;const selected=$(`#collection-grid [data-type="${code}"]`),cards=[...$('#collection-grid').querySelectorAll('.player-card')],columns=Math.max(1,Math.round($('#collection-grid').clientWidth/(selected.offsetWidth+12))),index=cards.indexOf(selected),end=Math.min(Math.floor(index/columns)*columns+columns-1,cards.length-1);cards[end].after(detail);detail.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'nearest'});}
  function clearGiftHash(){const url=new URL(location.href),params=new URLSearchParams(url.hash.slice(1));if(params.has('meet')){params.delete('meet');url.hash=params.toString();history.replaceState(history.state,'',url);}}
  function handleGift(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('meet'))return;const code=window.GameCollection.parseGift(location.hash,types);if(!code){const old=/^[EI][SN][TF][JP]$/.test(params.get('meet')||'');clearGiftHash();notify(old?'这是旧版 16 型分享链接。新版采用 42 种行为倾向，请重新测试后分享。':'人格链接不完整，让朋友重新分享一次吧。');return;}pendingGift=code;closeDialogs();const t=types[code],known=book.has(code);$('#gift-content').innerHTML=`<p class="gift-eyebrow">${known?'这位老朋友，图鉴里已经有了。':'朋友给你送来一种玩家倾向。'}</p><div class="gift-card card-${t.group}"><span class="gift-code mono">${code}</span>${character(code,'gift-character')}<h2 id="gift-title">${t.name}</h2><p>“${t.quote}”</p></div><p class="gift-description">${known?'重复收卡不会多占格子。去看看已经遇见的玩家吧。':'朋友可以同时有多种倾向。这张卡收进图鉴后，不会改变你的测试结果。'}</p><button class="button button-dark" data-action="claim-gift">${known?'已在图鉴，去看看':'收进我的图鉴'} <span>↓</span></button><button class="text-link" data-action="start">我也测测自己的玩法 →</button>`;openDialog($('#gift-dialog'));}
  function claimGift(){if(!pendingGift)return;const code=pendingGift,{added}=unlock(code,'friend');$('#gift-dialog').close();clearGiftHash();pendingGift=null;openCollection(code);notify(added?'收到！图鉴里多了一位玩家。':'已经收藏过啦，不会重复占格子。');}
  function resultLink(code){return window.GameCollection.giftURL(location.href,code,types);}
  async function share(){if(!result?.code)return;const code=result.code,t=types[code],link=resultLink(code),message=`这次我的一种明显倾向是「${t.name}」：${t.quote} 收下这张 GameBTI 人格卡，也来看看你的玩法。`;try{if(navigator.share&&location.protocol==='https:'){await navigator.share({title:'我的 GameBTI 玩家倾向',text:message,url:link});return;}if(navigator.clipboard&&isSecureContext){await navigator.clipboard.writeText(message+'\n'+link);notify('人格分享链接已复制，朋友点开就能收藏。');}else showCopyDialog(message+'\n'+link);}catch(error){if(error.name!=='AbortError')showCopyDialog(message+'\n'+link);}}
  function showCopyDialog(text){let d=$('#share-dialog');if(!d){d=document.createElement('dialog');d.id='share-dialog';d.className='about-dialog';document.body.append(d);}d.innerHTML='<button class="close-button" data-action="close" aria-label="关闭分享">×</button><h2>分享给你的搭子</h2><p>选中文字复制，朋友点开链接就能收下这张卡。</p><textarea aria-label="人格分享内容" class="share-copy" readonly></textarea>';d.querySelector('textarea').value=text;openDialog(d);d.querySelector('textarea').select();}
  function previewCard(blob,code){let d=$('#card-preview-dialog');if(!d){d=document.createElement('dialog');d.id='card-preview-dialog';d.className='card-preview-dialog';document.body.append(d);}const t=types[code],url=URL.createObjectURL(blob),filename=`GameBTI-${code}-${t.name}.png`;d.innerHTML=`<div class="dialog-top"><h2>收好这次的玩家倾向</h2><button class="close-button" data-action="close" aria-label="关闭人格卡预览">×</button></div><img class="card-preview-image" alt="${code} ${t.name} 人格卡"><p>长按图片保存到相册。你可以同时有多种倾向。</p><div class="card-preview-actions"><a class="button button-dark" download>保存图片 ↓</a><button class="button button-outline" hidden>分享图片 ↗</button></div><button class="text-link card-preview-link" data-action="share">让朋友也能收藏：分享这张人格链接 →</button>`;d.querySelector('img').src=url;const link=d.querySelector('a');link.href=url;link.download=filename;const file=new File([blob],filename,{type:'image/png'}),button=d.querySelector('.button-outline');if(navigator.canShare?.({files:[file]})){button.hidden=false;button.addEventListener('click',async()=>{try{await navigator.share({files:[file],title:`GameBTI · ${t.name}`,text:resultLink(code)});}catch(error){if(error.name!=='AbortError')notify('可以长按图片保存，再把人格链接发给朋友。');}});}d.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});openDialog(d);}
  const colors={team:'#dce7f0',self:'#e1d9ef',motivation:'#eee2ba',engagement:'#dbe7d4',interaction:'#f0d5c6',content:'#d5e9e8',completion:'#ebe4ce'};
  async function download(){
    if(!result?.code)return;const code=result.code,t=types[code],button=$('[data-action="download"]');button.disabled=true;button.textContent='正在生成…';
    try{if(document.fonts?.ready)await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1260;const ctx=canvas.getContext('2d');ctx.fillStyle=colors[t.group];ctx.fillRect(0,0,900,1260);ctx.fillStyle='#292d26';ctx.font='bold 35px Arial';ctx.fillText('gamebti',65,90);const mark=new Image();mark.src='assets/whale-mark.svg';await mark.decode();ctx.drawImage(mark,213,59,43,34);ctx.textAlign='right';ctx.font='18px monospace';ctx.fillText('PLAYER ID CARD · V2',835,86);ctx.strokeStyle='#292d2630';ctx.beginPath();ctx.moveTo(65,120);ctx.lineTo(835,120);ctx.stroke();ctx.textAlign='center';ctx.font='bold 94px Arial';ctx.fillText(code,450,265);ctx.font='bold 56px "Microsoft YaHei",sans-serif';ctx.fillText(t.name,450,350);ctx.font='22px "Microsoft YaHei",sans-serif';ctx.fillText(t.category,450,403);const image=new Image();image.src=t.sheet;await image.decode();const width=image.naturalWidth/4,height=image.naturalHeight/4;ctx.imageSmoothingEnabled=false;ctx.drawImage(image,t.spriteIndex%4*width,Math.floor(t.spriteIndex/4)*height,width,height,220,420,460,460);ctx.font='28px "Microsoft YaHei",sans-serif';ctx.fillText('“'+t.quote+'”',450,918);ctx.fillStyle='#5f6c55';ctx.font='24px "Microsoft YaHei",sans-serif';ctx.fillText(t.trait,450,982);ctx.fillStyle='#292d26';ctx.font='25px "Microsoft YaHei",sans-serif';ctx.fillText('你的玩法，不只一种。',450,1075);ctx.fillStyle='#6f7867';ctx.font='18px "Microsoft YaHei",sans-serif';ctx.fillText('认真玩游戏，随便做自己。',450,1124);ctx.font='17px "Microsoft YaHei",sans-serif';ctx.fillText('GameBTI · 仅供娱乐',450,1173);const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('empty')),'image/png'));if(mobile.matches)previewCard(blob,code);else{const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`GameBTI-${code}-${t.name}.png`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('人格卡已生成，看看浏览器的下载列表。');}}catch{notify('图片生成没成功，可以先分享人格链接。');}finally{button.disabled=false;button.innerHTML='保存这张人格卡 <span>↓</span>';}
  }
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.answer!==undefined){const id=plan[current];answers[id]=Number(b.dataset.answer);if(byId[id].phase==='initial'&&data.rounds[roundIndex].every(id=>data.has(answers,id)))plan=buildPlan(answers,roundIndex);save();document.querySelectorAll('.answer').forEach(option=>{const selected=Number(option.dataset.answer)===answers[id];option.classList.toggle('selected',selected);option.setAttribute('aria-pressed',String(selected));});$('.quiz-next').disabled=false;return;}if(b.dataset.resultType){if(result?.primaryIds.includes(b.dataset.resultType)){result.code=b.dataset.resultType;renderResult();scrollTo({top:0,behavior:'instant'});}return;}if(b.dataset.filter){filter=b.dataset.filter;renderCollection();return;}if(b.dataset.type){if(!$('#collection-dialog').open)openCollection(b.dataset.type);else previewType(b.dataset.type);return;}switch(b.dataset.action){case'start':start();break;case'continue-round':continueRound();break;case'next':next();break;case'previous':if(current>0){current--;save();renderQuiz();scrollTo(0,0);}break;case'home':showScreen('home');break;case'collection':openCollection();break;case'about':openDialog($('#about-dialog'));break;case'close':b.closest('dialog').close();break;case'claim-gift':claimGift();break;case'share':share();break;case'download':download();break;}});
  document.querySelectorAll('.brand,.footer-brand').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showScreen('home');}));
  $('#resume-button').addEventListener('click',()=>{const s=readSave();if(!s){updateResume();return;}answers=s.answers;roundIndex=s.roundIndex;plan=s.plan;current=s.current;result=s.complete?calculate(answers,roundIndex):null;if(result){result.primaryIds.forEach(code=>unlock(code,'self'));renderResult();showScreen('result');}else{renderQuiz();showScreen('quiz');}});
  document.addEventListener('keydown',event=>{if(screen!=='quiz'||document.querySelector('dialog[open]')||event.altKey||event.ctrlKey||event.metaKey||event.repeat)return;const index=Number(event.key)-1;if(Number.isInteger(index)&&index>=0&&index<byId[plan[current]].options.length)document.querySelector(`[data-answer="${index}"]`)?.click();});
  document.addEventListener('click',event=>{if(event.target.tagName==='DIALOG'){const box=event.target.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)event.target.close();}});
  $('#gift-dialog').addEventListener('close',()=>{if(!$('#gift-dialog').open){pendingGift=null;clearGiftHash();}});
  addEventListener('storage',event=>{if(event.key==='gamebti-collection-v2'){book=window.GameCollection.create(types,()=>localStorage);refreshCollection();}});
  const saved=readSave();if(saved?.complete){calculate(saved.answers,saved.roundIndex).primaryIds.forEach(code=>{if(!book.source(code).self)book.unlock(code,'self');});}
  if(!saved){try{if(localStorage.getItem('gamebti-save-v1')||localStorage.getItem('gamebti-collection-v1')||localStorage.getItem('gamebti-behaviors-save-v2'))$('#legacy-notice').hidden=false;}catch{}}
  refreshCollection();updateResume();handleGift();addEventListener('hashchange',handleGift);
})();
